// Code node "Resolve month"  (mode: Run Once for All Items)
// Input : the Webhook (POST /webhook/spend-report, body {"month": "2026-09"}), the schedule or the manual trigger.
// Output: ONE item { valid, error, month_start: "2026-09-01", month_label: "2026-09" }.
//   Schedule / manual run: the previous calendar month.
//   Webhook run: the month from the body; it must look like YYYY-MM and must not be in the future.

const pad = (n) => String(n).padStart(2, '0');
const now = new Date();
const thisMonth = `${now.getFullYear()}-${pad(now.getMonth() + 1)}`;

// Previous month as "YYYY-MM"
const prev = new Date(now.getFullYear(), now.getMonth() - 1, 1);
const previousMonth = `${prev.getFullYear()}-${pad(prev.getMonth() + 1)}`;

const body = $input.first().json.body ?? {};
const requested = body.month === undefined ? previousMonth : String(body.month).trim();

let error = null;
if (!/^\d{4}-(0[1-9]|1[0-2])$/.test(requested)) error = 'month must look like 2026-09';
else if (requested > thisMonth) error = `month ${requested} is in the future`;

return [{
  json: {
    valid: error === null,
    error,
    month_start: `${requested}-01`,
    month_label: requested,
  },
}];

// Code node "Shape report"  (mode: Run Once for All Items)
// Input : the row from "Compute report" ({ report: { month, by_tool, by_team_tool } }).
// Output: ONE item { month, totals, by_tool, by_team_tool }.
//   totals = overall numbers, top 3 variances, top 3 idle-cost tools, biggest month-over-month movers.
// "totals" is what gets stored in monthly_reports and (aggregates only) sent to the local model.

const report = $input.first().json.report;
const byTool = report.by_tool ?? [];
const byTeamTool = report.by_team_tool ?? [];
if (byTool.length === 0) throw new Error(`No spend data for ${report.month}`);

const round2 = (x) => Math.round(Number(x) * 100) / 100;
const usd = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' });
const sum = (rows, key) => round2(rows.reduce((total, row) => total + Number(row[key] ?? 0), 0));
const pct = (part, whole) => (whole ? Math.round((part / whole) * 1000) / 10 : null);

// Overall
const actual = sum(byTool, 'actual');
const budget = sum(byTool, 'budget');
const activeUsers = sum(byTool, 'active_users');
const prevActual = sum(byTool.filter((t) => t.prev_actual !== null), 'prev_actual');
const overall = {
  actual, budget,
  variance: round2(actual - budget),
  variance_pct: pct(actual - budget, budget),
  committed: sum(byTool, 'committed'),
  usage_spend: sum(byTool, 'usage_spend'),
  active_users: activeUsers,
  cost_per_active_user: activeUsers ? round2(actual / activeUsers) : null,
  idle_cost: sum(byTool, 'idle_cost'),
  prev_actual: prevActual || null,
  mom_change: prevActual ? round2(actual - prevActual) : null,
  mom_pct: prevActual ? pct(actual - prevActual, prevActual) : null,
};

// Top 3 team + tool combinations over budget (only rows that have a budget)
const topVariances = byTeamTool
  .filter((r) => r.budget !== null && Number(r.variance) > 0)
  .sort((a, b) => b.variance - a.variance)
  .slice(0, 3)
  .map((r) => ({ team: r.team, tool: r.tool, actual: r.actual, budget: r.budget, variance: r.variance, variance_pct: r.variance_pct }));

// Teams whose total across all tools is over budget
const teamTotals = {};
for (const r of byTeamTool.filter((row) => row.budget !== null)) {
  const t = (teamTotals[r.team] ??= { actual: 0, budget: 0 });
  t.actual += Number(r.actual);
  t.budget += Number(r.budget);
}
const teamsOverBudget = Object.entries(teamTotals)
  .filter(([, t]) => t.actual > t.budget)
  .map(([team, t]) => ({ team, variance: round2(t.actual - t.budget), variance_pct: pct(t.actual - t.budget, t.budget) }))
  .sort((a, b) => b.variance - a.variance);

// Top 3 tools by idle cost
const topIdle = [...byTool]
  .sort((a, b) => b.idle_cost - a.idle_cost)
  .slice(0, 3)
  .map((t) => ({ tool: t.tool, idle_cost: t.idle_cost }));

// Biggest month-over-month movers (needs a previous month)
const momMovers = byTool
  .filter((t) => t.mom_change !== null)
  .sort((a, b) => Math.abs(b.mom_change) - Math.abs(a.mom_change))
  .slice(0, 3)
  .map((t) => ({ tool: t.tool, mom_change: t.mom_change, mom_pct: t.mom_pct, actual: t.actual, prev_actual: t.prev_actual }));

const totals = {
  month: report.month,
  currency: 'USD',
  overall,
  teams_over_budget: teamsOverBudget,
  top_variances: topVariances,
  top_idle_tools: topIdle,
  mom_movers: momMovers,
};

return [{ json: { month: report.month, totals, by_tool: byTool, by_team_tool: byTeamTool, total_text: usd.format(actual) } }];

// Code node "Build Ollama request"  (mode: Run Once for All Items)
// Input : "Shape report" (and "Config" for the model name).
// Output: ONE item { request } -> the HTTP node sends  {{ JSON.stringify($json.request) }}  to Ollama /api/chat.
// Only aggregated numbers go to the model: tool and team names with money, never people or emails.
// "format" is a JSON schema, so Ollama is forced to answer in that shape.

const cfg = $('Config').first().json.cfg;
const t = $('Shape report').first().json.totals;

const facts = {
  month: t.month,
  currency: t.currency,
  overall: t.overall,
  teams_over_budget: t.teams_over_budget,
  top_variances_team_and_tool: t.top_variances,
  top_idle_cost_tools: t.top_idle_tools,
  biggest_month_over_month_changes: t.mom_movers,
};

const schema = {
  type: 'object',
  properties: {
    headline: { type: 'string' },
    three_points: { type: 'array', items: { type: 'string' }, minItems: 3, maxItems: 3 },
    recommended_action: { type: 'string' },
  },
  required: ['headline', 'three_points', 'recommended_action'],
};

const request = {
  model: cfg.ollama_summary_model ?? 'llama3.1:8b',
  stream: false,
  format: schema,
  options: { temperature: 0.2 },
  messages: [
    {
      role: 'system',
      content: 'You are a finance analyst writing a short monthly software-spend summary for a finance team. '
        + 'Use ONLY the numbers in the data you are given, copied exactly. Never calculate new numbers or percentages and never invent figures. Money is in USD. '
        + 'Answer with: a one-sentence headline, exactly three short points, and one recommended action.',
    },
    { role: 'user', content: `Monthly license spend data (JSON):\n${JSON.stringify(facts)}` },
  ],
};

return [{ json: { request } }];

// Code node "Check summary" (first try) and "Check summary retry" (second try). Same code in both  (mode: Run Once for All Items)
// Input : the answer of the Ollama HTTP node. If Ollama was unreachable the item holds an "error" instead.
// Output: ONE item { ok, source, summary: { headline, three_points, recommended_action }, reason }.
//   First try fails      -> ok = false, the workflow asks Ollama once more.
//   Second try fails too -> a summary built from a template, source = 'template'. The report is never blocked.

// false in "Check summary" (first try), true in "Check summary retry" (second try, falls back to the template)
const isRetry = false;
const totals = $('Shape report').first().json.totals;
const input = $input.first().json;

// ---- 1. is the answer usable? ----
function parse(response) {
  if (response.error) return { reason: `Ollama call failed: ${response.error.message ?? response.error}` };
  let data;
  try {
    data = JSON.parse(response.message?.content ?? '');
  } catch (e) {
    return { reason: 'answer is not valid JSON' };
  }
  const text = (value) => typeof value === 'string' && value.trim().length > 0;
  if (!text(data.headline)) return { reason: 'missing headline' };
  if (!Array.isArray(data.three_points) || data.three_points.length !== 3 || !data.three_points.every(text)) {
    return { reason: 'three_points must be exactly 3 non-empty strings' };
  }
  if (!text(data.recommended_action)) return { reason: 'missing recommended_action' };
  return {
    summary: {
      headline: data.headline.trim(),
      three_points: data.three_points.map((p) => p.trim()),
      recommended_action: data.recommended_action.trim(),
    },
  };
}

const parsed = parse(input);
if (parsed.summary) return [{ json: { ok: true, source: 'ollama', summary: parsed.summary, reason: null } }];
if (!isRetry) return [{ json: { ok: false, source: null, summary: null, reason: parsed.reason } }];

// ---- 2. template summary (second failure) ----
const usd = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
const signed = (n) => `${n >= 0 ? '+' : '-'}${usd.format(Math.abs(n))}`;
const o = totals.overall;
const top = totals.top_variances[0];
const idle = totals.top_idle_tools[0];
const mover = totals.mom_movers[0];

const points = [
  top
    ? `Largest overspend: ${top.team} on ${top.tool}, ${signed(top.variance)} over budget.`
    : 'No team is over budget on any tool.',
  idle
    ? `Idle seats cost ${usd.format(o.idle_cost)} in total; most of it is ${idle.tool} (${usd.format(idle.idle_cost)}).`
    : 'No idle seats were found.',
  mover
    ? `Biggest change from last month: ${mover.tool}, ${signed(mover.mom_change)}.`
    : 'No previous month to compare with.',
];
const summary = {
  headline: `${totals.month}: ${usd.format(o.actual)} spent against a ${usd.format(o.budget)} budget `
    + `(${o.variance >= 0 ? '+' : ''}${o.variance_pct ?? 0}%).`,
  three_points: points,
  recommended_action: idle
    ? `Review the idle ${idle.tool} seats and reclaim the unused ones.`
    : 'No action needed this month.',
};
return [{ json: { ok: true, source: 'template', summary, reason: parsed.reason } }];

// Code node "Check summary" (first try) and "Check summary retry" (second try). Same code in both  (mode: Run Once for All Items)
// Input : the answer of the Ollama HTTP node. If Ollama was unreachable the item holds an "error" instead.
// Output: ONE item { ok, source, summary: { headline, three_points, recommended_action }, reason }.
//   First try fails      -> ok = false, the workflow asks Ollama once more.
//   Second try fails too -> a summary built from a template, source = 'template'. The report is never blocked.

// false in "Check summary" (first try), true in "Check summary retry" (second try, falls back to the template)
const isRetry = true;
const totals = $('Shape report').first().json.totals;
const input = $input.first().json;

// ---- 1. is the answer usable? ----
function parse(response) {
  if (response.error) return { reason: `Ollama call failed: ${response.error.message ?? response.error}` };
  let data;
  try {
    data = JSON.parse(response.message?.content ?? '');
  } catch (e) {
    return { reason: 'answer is not valid JSON' };
  }
  const text = (value) => typeof value === 'string' && value.trim().length > 0;
  if (!text(data.headline)) return { reason: 'missing headline' };
  if (!Array.isArray(data.three_points) || data.three_points.length !== 3 || !data.three_points.every(text)) {
    return { reason: 'three_points must be exactly 3 non-empty strings' };
  }
  if (!text(data.recommended_action)) return { reason: 'missing recommended_action' };
  return {
    summary: {
      headline: data.headline.trim(),
      three_points: data.three_points.map((p) => p.trim()),
      recommended_action: data.recommended_action.trim(),
    },
  };
}

const parsed = parse(input);
if (parsed.summary) return [{ json: { ok: true, source: 'ollama', summary: parsed.summary, reason: null } }];
if (!isRetry) return [{ json: { ok: false, source: null, summary: null, reason: parsed.reason } }];

// ---- 2. template summary (second failure) ----
const usd = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
const signed = (n) => `${n >= 0 ? '+' : '-'}${usd.format(Math.abs(n))}`;
const o = totals.overall;
const top = totals.top_variances[0];
const idle = totals.top_idle_tools[0];
const mover = totals.mom_movers[0];

const points = [
  top
    ? `Largest overspend: ${top.team} on ${top.tool}, ${signed(top.variance)} over budget.`
    : 'No team is over budget on any tool.',
  idle
    ? `Idle seats cost ${usd.format(o.idle_cost)} in total; most of it is ${idle.tool} (${usd.format(idle.idle_cost)}).`
    : 'No idle seats were found.',
  mover
    ? `Biggest change from last month: ${mover.tool}, ${signed(mover.mom_change)}.`
    : 'No previous month to compare with.',
];
const summary = {
  headline: `${totals.month}: ${usd.format(o.actual)} spent against a ${usd.format(o.budget)} budget `
    + `(${o.variance >= 0 ? '+' : ''}${o.variance_pct ?? 0}%).`,
  three_points: points,
  recommended_action: idle
    ? `Review the idle ${idle.tool} seats and reclaim the unused ones.`
    : 'No action needed this month.',
};
return [{ json: { ok: true, source: 'template', summary, reason: parsed.reason } }];

// Code node "Build Slack report"  (mode: Run Once for All Items)
// Input : the summary from "Check summary" or "Check summary retry"; the numbers come from "Shape report".
// Output: ONE item { text, blocks } for the Slack node:
//   Message Type "Blocks", Blocks = {{ JSON.stringify({ blocks: $json.blocks }) }}, Text = {{ $json.text }}

// The summary comes from the first try, or from the retry when the first answer was not usable.
const check = $('Check summary retry').isExecuted ? $('Check summary retry').first().json : $('Check summary').first().json;
const { totals, by_tool: byTool } = $('Shape report').first().json;
const o = totals.overall;
const summary = check.summary;

const usd = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
const signedPct = (p) => (p === null || p === undefined ? 'n/a' : `${p >= 0 ? '+' : ''}${p}%`);
const flag = (variance) => (variance > 0 ? ':red_circle:' : ':large_green_circle:');

// One "field" per tool: actual / budget and the variance (Slack allows 10 fields per section)
const fields = byTool.slice(0, 10).map((t) => ({
  type: 'mrkdwn',
  text: `*${t.tool}*\n${usd.format(t.actual)} / ${usd.format(t.budget)}  ${flag(t.variance)} ${signedPct(t.variance_pct)}`,
}));

const where = check.source === 'ollama'
  ? 'Summary written by the local model; only aggregated numbers were sent to it.'
  : 'Summary built from a template (the local model gave no usable answer).';

const blocks = [
  { type: 'header', text: { type: 'plain_text', text: `Spend report ${totals.month}` } },
  { type: 'section', text: { type: 'mrkdwn', text: `*${summary.headline}*` } },
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: `*Total* ${usd.format(o.actual)} vs budget ${usd.format(o.budget)} (${signedPct(o.variance_pct)})`
        + ` · idle seats ${usd.format(o.idle_cost)}`
        + (o.cost_per_active_user === null ? '' : ` · ${usd.format(o.cost_per_active_user)} per active user`),
    },
  },
  { type: 'section', fields },
  { type: 'section', text: { type: 'mrkdwn', text: summary.three_points.map((p) => `• ${p}`).join('\n') } },
  { type: 'section', text: { type: 'mrkdwn', text: `:dart: *Recommended action:* ${summary.recommended_action}` } },
  { type: 'context', elements: [{ type: 'mrkdwn', text: where }] },
];

return [{ json: { text: `Spend report ${totals.month}: ${summary.headline}`, blocks } }];

// Code node "Make CSV"  (mode: Run Once for All Items)
// Input : "Shape report". Output: ONE item { csv, file_name } -> "Convert to File" (operation "Convert to Text File",
//   Source Property = csv, File Name = {{ $json.file_name }}), then the Slack file upload.
// One row per team and tool, same numbers as the report.

const { month, by_team_tool: rows } = $('Shape report').first().json;

const columns = ['team', 'tool', 'actual', 'budget', 'variance', 'variance_pct',
  'accounts', 'active_users', 'cost_per_active_user', 'idle_cost'];

// Wrap a value in quotes only when it needs them (comma, quote or line break)
function cell(value) {
  if (value === null || value === undefined) return '';
  const text = String(value);
  return /[",\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text;
}

const lines = [columns.join(',')];
for (const row of rows) lines.push(columns.map((c) => cell(row[c])).join(','));

return [{ json: { csv: lines.join('\n') + '\n', file_name: `spend-${month}.csv` } }];
